```python
RT_PGREP = 'pgrep -af "rt[.](run|pool|deltas)" || true'

def _wd_ranks():
    try:
        with open(f'{POUTH}/watchdog_state.json') as f:
            st = json.load(f)
        return st.get('ranks', []) if isinstance(st, dict) else []
    except Exception:
        return []          # torn or partial write: skip this poll

def wait_all_exit(entries, project, poll=60, stale_hours=10, settle=360):
    t0 = time.time()
    pids = {e['rank']: {e['pid']} if e.get('pid') else set() for e in entries}
    def scan():
        for rk in _wd_ranks():
            if rk.get('project') != project or rk.get('rank') not in pids:
                continue
            if rk.get('status') == 'paused':
                halt(project, f"watchdog 已暂停 rank {rk['rank']}（第4次卡死），按 H-2 不续跑")
            if rk.get('pid'):
                pids[rk['rank']].add(int(rk['pid']))      # accumulate, never replace
        alive = [r for r, ps in pids.items() if any(os.path.exists(f'/proc/{p}') for p in ps)]
        rt, _ = sh_out(RT_PGREP)
        return alive, rt
    while True:
        alive, rt = scan()
        CUR['detail'] = f"{project}: alive ranks {alive} rt={'yes' if rt else 'no'}"; save_cur()
        if not alive and not rt:
            time.sleep(settle)   # longer than the watchdog's kill -> GPU<1GB -> restart window (watchdog.py 99-117, <=300 s)
            alive, rt = scan()
            if not alive and not rt:
                return True
        if time.time() - t0 > stale_hours * 3600:
            return False
        time.sleep(poll)
